import{_ as p,H as a,f as t,i}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"09-认识职场：理解职场中的事和人","description":"","frontmatter":{},"headers":[{"level":2,"title":"职场中的事","slug":"职场中的事","link":"#职场中的事","children":[{"level":3,"title":"职场工作全景图","slug":"职场工作全景图","link":"#职场工作全景图","children":[]},{"level":3,"title":"从职场工作全景图看日常工作","slug":"从职场工作全景图看日常工作","link":"#从职场工作全景图看日常工作","children":[]}]},{"level":2,"title":"职场中的人","slug":"职场中的人","link":"#职场中的人","children":[{"level":3,"title":"及时沟通，对齐目标","slug":"及时沟通-对齐目标","link":"#及时沟通-对齐目标","children":[]},{"level":3,"title":"看到诉求，理解恐惧","slug":"看到诉求-理解恐惧","link":"#看到诉求-理解恐惧","children":[]}]},{"level":2,"title":"小结时刻","slug":"小结时刻","link":"#小结时刻","children":[]},{"level":2,"title":"聊聊发展","slug":"聊聊发展","link":"#聊聊发展","children":[]}],"relativePath":"程序员职业规划手册/09-认识职场：理解职场中的事和人.md","filePath":"程序员职业规划手册/09-认识职场：理解职场中的事和人.md","lastUpdated":1795563381000}'),l={name:"程序员职业规划手册/09-认识职场：理解职场中的事和人.md"};function n(r,e,s,h,o,E){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="_09-认识职场-理解职场中的事和人" tabindex="-1">09-认识职场：理解职场中的事和人 <a class="header-anchor" href="#_09-认识职场-理解职场中的事和人" aria-label="Permalink to &quot;09-认识职场：理解职场中的事和人&quot;">​</a></h1><p>你好，我是雪梅。</p><p>如果你有时忙忙碌碌，效果却不好，又或者有的时候你和别人的合作不流畅，那这节课就是为你准备的。</p><p>理解职场中的事，是为了先看全景、先看环境，才会让你的忙碌有的放矢。而理解职场中的人，是因为理解协作伙伴的角色和诉求，才能高效、和谐地推进合作。</p><p>咱们无论做什么事，都不要急着一头扎进去，先看到全景，才能游刃有余。</p><h2 id="职场中的事" tabindex="-1">职场中的事 <a class="header-anchor" href="#职场中的事" aria-label="Permalink to &quot;职场中的事&quot;">​</a></h2><p>说到职场中的事，先给你分享一个小 A 的故事。</p><p>小 A 是一个特别靠谱的技术人，最近从大厂跳槽到一家中型企业，带一个 10 人左右的团队。</p><p>加入新公司之后，他发现了很多问题。比如系统架构有很多隐患，小伙伴的工作效率不高，沟通意识也很薄弱。他很想扭转团队的局面，所以花了很多时间去处理系统中的问题，手把手带小伙伴，帮助大家成长。每天很努力地工作，经常十一二点下班。</p><p>结果两个月后，他的老板却说对他的工作不满意……那小 A 的问题出在哪里呢？</p><p>你先想想，企业招聘这个“带 10 人左右的团队”的岗位，是想解决什么问题？或者说，系统架构的优化和团队内部的培养，是当前这个岗位的首要目标吗？</p><p>小 A 的一系列动作，就是没有理解岗位要解决的核心问题，也是“只见树木不见森林”的典型表现，没有把自己的岗位放到所在的企业组织里来理解，更没有看到自己工作的全景图。</p><h3 id="职场工作全景图" tabindex="-1">职场工作全景图 <a class="header-anchor" href="#职场工作全景图" aria-label="Permalink to &quot;职场工作全景图&quot;">​</a></h3><p>职场工作全景图，是一幅岗位价值与企业最终价值的关系图。上一节我们提到过，职场的产生是社会化大分工的结果，我们当前岗位所做的事情只是企业中的一部分。看这张全景图，就好比俯瞰自己的工作，看自己日常的工作是与哪些角色深度协同的。</p><p>这么说可能有些抽象，举个例子，一个做外卖商家端的研发小 B，如何理解自己工作的全景图呢？</p><p>首先，要理解企业存在的目的是为客户创造价值，从而获取利润。外卖企业的主要收入来源是用户下单付款，以及平台对于商家的抽佣。小 B 今天完成商家端订单管理功能的开发，并没有直接给企业创造利润，而是通过业务，尤其是一线的商圈经理去销售，让商户入驻平台，才给平台创造了利润。所以从研发这个岗位开始，再到企业最终价值的中间，是存在一条价值传导链的。这个链条从研发到产品到业务，最后传递到客户，就是小 B 的业务价值。</p><p>其次，企业作为一个组织，内部的效率、人才梯队也是组织健康的重要指标。如果小 B 是一个优秀的工程师，不只自己能把项目做好，还能推动流程的优化，帮助团队带新人，就产生了很好的组织价值。</p><p>因此，企业作为雇佣方，对于员工小 B 的价值考虑，有业务价值，还有组织价值。小 B 工作的全局可能如下示意图所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A8%8B%E5%BA%8F%E5%91%98%E8%81%8C%E4%B8%9A%E8%A7%84%E5%88%92%E6%89%8B%E5%86%8C/images/09-%25E8%25AE%25A4%25E8%25AF%2586%25E8%2581%258C%25E5%259C%25BA/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A8%8B%E5%BA%8F%E5%91%98%E8%81%8C%E4%B8%9A%E8%A7%84%E5%88%92%E6%89%8B%E5%86%8C/images/09-%25E8%25AE%25A4%25E8%25AF%2586%25E8%2581%258C%25E5%259C%25BA/1.png" alt=""></a></p><p>除了静态理解你职场工作的全景图之外，我还建议你增加一些动态视角。比如时不时给自己按个暂停键，从手中忙碌的工作中后退一步，站在你的 N+1（上一级）、N+2（上级的上级）角度去思考。想想他们在忙什么？你合作的上下游在忙什么？你所在的业务单元今年有哪些重要的 OKR？目前面临哪些挑战？</p><p>从这些信息中，你可以判断自己当下关注的优先事项和目标是否正确。它们对公司来说，是真正有价值的东西，还是只是一些细枝末叶？同时，它也会时刻提醒我们的工作要以终为始，要知道自己写的代码跟企业创造价值中间的关系。</p><h3 id="从职场工作全景图看日常工作" tabindex="-1">从职场工作全景图看日常工作 <a class="header-anchor" href="#从职场工作全景图看日常工作" aria-label="Permalink to &quot;从职场工作全景图看日常工作&quot;">​</a></h3><p>刚才我们提到，在职场工作的全景图中，技术岗位产生的价值分为业务价值和组织价值两部分，这两个价值思路可以更好地指导我们技术人的日常工作。</p><p>技术人的工作大体可以分为这么几大类。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A8%8B%E5%BA%8F%E5%91%98%E8%81%8C%E4%B8%9A%E8%A7%84%E5%88%92%E6%89%8B%E5%86%8C/images/09-%25E8%25AE%25A4%25E8%25AF%2586%25E8%2581%258C%25E5%259C%25BA/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A8%8B%E5%BA%8F%E5%91%98%E8%81%8C%E4%B8%9A%E8%A7%84%E5%88%92%E6%89%8B%E5%86%8C/images/09-%25E8%25AE%25A4%25E8%25AF%2586%25E8%2581%258C%25E5%259C%25BA/2.png" alt=""></a></p><p>第一类，与业务目标强相关的，这是最容易产出业务价值的。比如完成产品需求开发，用技术手段解决业务痛点问题，帮助业务达成目标等。按照前面提到的价值传导链路，这部分的工作价值可以直接用业务结果来衡量。</p><p>比如，可以是 GMV 的提升，某营销系统的上线，帮助提升了多少客户复购率，产生了多少GMV。也可以是成本降低，比如优化了用户某个操作链路，用户咨询量下降了多少，减少了多少客服进线量。还可以是效率提升，比如调度系统的优化，帮助外卖配送员的人效提升多少等等。</p><p>这类工作需要你在做之前就理清楚清晰的衡量指标，做的过程中做好埋点分析，发布之后做好数据验证和回收。</p><p>第二类，业务保障型工作，这部分有业务价值，也有组织价值。典型的工作有技术人做的稳定性建设，用技术手段优化用户体验，引入新技术提升开发效率，或者系统重构优化等等工作。</p><p>这部分属于技术人本身的基础工作，可以明确定义可衡量的技术指标有故障数、线上 Bug数、页面秒开率、Crash 率等结果指标，也有监控覆盖率等过程指标。总之，你需要养成数据思维，用数据指导你的工作，帮助你显化结果，也能用数据指导后续迭代。</p><p>第三类，组织需要的事务型工作，也就是保障这么大组织能顺利运转需要做的工作，这部分主要产生的是组织价值。比如各种例会、培训、分享、活动等等。你可以把自己做项目的经验总结成文档分享给大家，把你看到团队合作中的问题形成 SOP，形成流程机制，帮助团队提效。</p><p>以上三种都是常规的工作，除了这些，还有第四类，突发或者创新的工作。</p><p>举个例子，在大厂工作的小 C 最近所在的业务单元与另一个业务单元合并，既涉及系统的融合，还涉及组织的融合。于是小 C 经常接到 Leader 的需求，“小 C，你去研究下 XX”。</p><p>刚开始小 C 还很积极地去研究，后来发现大多的调研就像石子扔进湖里，毫无动静。小 C 开始不安起来，觉得“天天没完没了地调研，对业务增长有什么意义？”</p><p>其实，这是组织在一个特殊阶段必然会面临的问题。庞大业务的融合，中间 90% 的调研看起来是“试错”，从某种程度来讲，也是在“试对”，这是组织融合必须付出的成本。一个处于发展早期的企业，甚至现在的很多公司也经常会面临这样的情况，今天试试做这个，明天试试做那个，很多产品生存空间可能也就几个月。</p><p>技术人常常被这些变化搞得心力交瘁，一开始满心欢喜地投入，干得热火朝天，突然说停就停了，但在多变的市场环境下，这确实是一种客观存在。</p><p>对于技术人来说，写代码是 0-1 世界，极度精准，导致我们对确定性有一种执念，不过真实的世界恰恰是非常不确定的。所以一方面我们需要调整心态，放弃一些执念，另一方面要像上一节提到的借事修人，你仍然可以在变化的事中找到自己的能力提升点。</p><p>如果你经历的变化太多，或者这些变化极大影响了你对于自己发展的诉求，那就回到主人翁状态，选择更适合自己的环境。</p><h2 id="职场中的人" tabindex="-1">职场中的人 <a class="header-anchor" href="#职场中的人" aria-label="Permalink to &quot;职场中的人&quot;">​</a></h2><p>相比职场中的事，其实更大的挑战来自职场中的人。很多人一提起职场，就想起油腻的厚黑学，其实没那么夸张。</p><p>如果你真正理解了职场中的人，可以帮助你缓解一半以上对于职场中各种复杂人际关系的误会。为啥这么说呢？咱们还是从具体案例入手。</p><h3 id="及时沟通-对齐目标" tabindex="-1">及时沟通，对齐目标 <a class="header-anchor" href="#及时沟通-对齐目标" aria-label="Permalink to &quot;及时沟通，对齐目标&quot;">​</a></h3><p>最基础的，技术小伙伴大多性格内向，很多人会说“我不会来事，所以经常吃亏”。</p><p>如果你仔细追问，很多人说的“来事儿”指的是别人爱跟老板沟通，事情还没做出来，就先跟老板聊。要不就是觉得别人屁大点事都要“早请示、晚汇报”，而自己只会埋头苦干，没事绕着老板走，所以认为自己“不会来事儿”。</p><p>而如果你理解了职场中的事，理解职场工作全景图，就会发现作为员工定期向老板汇报工作，这根本不是什么“会来事儿”，而是你的基本义务，没做到，那是你自己失责。</p><p>为什么这么说？因为老板需要从你这里获取更精准的信息，才能更好地做判断。就拿 OKR 的落地来说，看起来是一层层落地拆解，但事实上，OKR 从来不是单向的，一个大的 O 在部门到底如何拆解，是需要一线小伙伴给老板贡献很多输入的，这样才能更好地制定 OKR，这是一个双向的过程。</p><p>日常的项目管理更是如此，风险通报、问题同步、资源协调，都需要不断和老板做沟通，帮助老板更好地做决策。</p><p>你可能只看到别人“会来事儿”。可能他不是你以为的只会虚头巴脑地套近乎，而是有自己的思考。在跟老板的沟通中，他能获得更多对工作的反馈，有了反馈之后，就能更快速地纠偏，他的迭代速度会比你快很多。</p><p>当然，向上沟通是需要技巧的，这个我们在第三章会中会谈到。但所有技能的前提是意识，意识到这件事的重要性。理解了它的价值，才能帮你打通一些向上沟通的卡点。</p><p>再说第二个问题，合作障碍。</p><p>对于很多技术人来说，跨部门、跨角色的合作都是一件挺痛苦的事。要么发起一件事情，求爷爷告奶奶，别人磨磨唧唧就是不配合，要么遇到一个不讲理的人，两句话就怼起来了。</p><p>我年轻的时候血气方刚，碰到跨部门合作中的冲突，常常会无所不用“奇技”。比如在有大老板在的群里 @对方，发邮件，飘红加粗 @XX，项目风险第一时间同步所有人，再搞不定就“三顾茅庐”“软磨硬泡”等等，但常常费力不讨好。</p><p>后来随着自己职场经历的丰富，才真切体会到一切合作的基础是共同目标，只要我们的目标是一致的，很多问题都可以化解。不管对方是说话特别直，让你在会上很没颜面，还是特别强势，言语中带着火药味，还是表面态度很好，实际可能和稀泥……都不重要，只要目标一致，大家就可以合作。你不喜欢的人，不代表不可以合作，职场本身也承载不了那么多个人情绪。</p><h3 id="看到诉求-理解恐惧" tabindex="-1">看到诉求，理解恐惧 <a class="header-anchor" href="#看到诉求-理解恐惧" aria-label="Permalink to &quot;看到诉求，理解恐惧&quot;">​</a></h3><p>混职场不需要厚黑学，但确实要理解一点点基础的人性。我估计一说起人性，大家都觉得很抽象，在我看来，就是你要知道不同的人身上不同的利益诉求和恐惧。</p><p>给你讲个故事。小 D 是个特别靠谱的技术人，最近老板安排了个任务，要调研一个技术，调研完之后要在整个大部门推广运用。这项技术小 D 之前完全没有基础，很痛苦，他打听到旁边的部门之前试点过，小 E 在这方面很有经验。于是赶紧去找小 E 请教，小 E 也是一个特别nice 的技术人，很热心地帮他解答了很多问题。</p><p>在小 E 的帮助之下，小 D 成功地完成调研，并且在整个部门大力推广落地，得到了部门大老板的高度认可。在项目总结邮件中，小 D 洋洋洒洒分享了很多思考，却忘记了感谢小 E。后来小 D 再去请教小 E 时，小 E 已经不搭理自己了。</p><p>在这个故事中，小 D 做错了什么？你可能会说，技术人帮助人不是本分吗？小 E 也太矫情了。其实如果小 D 的项目没有成功，可能什么也不会发生，但偏偏小 D 的项目非常成功，产生了利益，有利益就一定要有利益分配，小 D 没有看到小 E 身上的利益诉求。</p><p>那什么是不同人的恐惧呢？我再给你讲个故事。</p><p>小 F 是做测试的，最近在公司的战略级项目中，每天忙得昏天暗地的。前期研发不太配合，现在项目 Deadline 一天天逼近，风险越来越多。按她的经验，很大概率要延期。她三番五次找老板沟通风险，想把排期往后延，但老板都坚决不同意 Delay，只答应可以加人，但凭她的经验，这个时候加人，其实于事无补……她无比委屈地问我该怎么办。</p><p>我说，你有没有想过战略级项目，如果你感受到的压力值是 100 分，你的老板压力值可能是1000 分，甚至更高。如果各个部门之间合作不畅，他可能还要“挡很多子弹&quot;。在极度高压的时候，老板更需要是一个“跟我站在一起”的积极态度，而不是“这里不行，那里有风险！”</p><p>小 F 问，这不是昧着良心吗？我说，不是隐藏风险。你可以说，老板，我会全力去做。同时把可能的风险、需要的资源以及可能的预案，用一个完整的方案呈现出来汇报给 Leader。说白了，这个时候，态度第一，解决问题第二。</p><p>在这个故事中，确定的 Deadline，在 Leader 看来就是一个对外的承诺，涉及那么多人，那么多部门，谁第一个破坏 Deadline，谁就需要承担后果，战略级项目延期的后果就是 Leader 的恐惧。</p><p>你会发现，我们这里说到的“利益”和“恐惧”，就是基础人与人相处的“换位思考”。在组织中，不同的岗位都有自己的角色诉求，也有这个岗位需要处理的挑战和工作。如果你理解了人与人相处的基本逻辑，同时理解了当人处在职场这个游戏场中，都有不同的“角色要求”，很多合作中的问题可能就豁然开朗了。</p><p>当然，我们聊了这么多关于职场中的事和人，还需要考虑企业文化。很多技术人觉得企业文化特别虚，其实企业文化是企业的价值观，诠释企业看重的是什么，选人的标准，做事的方式。也就是提倡什么行为，反对什么行为，这样持久下来，什么样的人会在企业里留下来，什么样的人又会离开，都跟企业文化息息相关。企业文化，可以说是你职场工作的土壤。</p><p>企业文化的冲突也是最难受的冲突，因为这种冲突来自价值观层面。一个在互联网工作很多年的小伙伴跳到一家外企，可能会有诸多不适。比如互联网可能强调积极主动、有责无界，而外企往往强调流程机制、边界清晰。比如互联网可能强调小步快跑，而外企可能节奏会慢很多等等。有的企业文化注重人文关怀，有的企业文化强调正确，理性第一……</p><p>其实都没有对和错，只是企业创始人和原始班底选择了这种文化，并且一直在践行这些文化。作为职场人，看懂哪些是企业文化对于事和人的影响，也会帮助你减少很多心理摩擦。</p><h2 id="小结时刻" tabindex="-1">小结时刻 <a class="header-anchor" href="#小结时刻" aria-label="Permalink to &quot;小结时刻&quot;">​</a></h2><p>这一节咱们聊了很多关于职场中的事和人。我给了你一个工具，“职场工作全景图”，指导自己做事的方向。重新理解了“不会来事儿”到底是啥意思，还分享了如何从利益和恐惧的角度来看待自己合作的同事。</p><p>当然了，职场本身还是有一定的复杂性的。对于身在职场中的我们来说，除了读懂职场游戏规则，理解了职场中的事和人，还要摸爬滚打中澄清自己做事的原则，找到自己的风格。</p><p>你可以慢慢找到自己做事的底线。比如我做一线的时候，给自己定的一个做事底线是“不给别人挖坑”，代码即使写得没那么优雅，但一定是可读性强、注释充分、日志规范的，自己模块的问题一定从根本上解决，即使没时间，加班加点也不能随便糊弄。在带团队时，我也会用这个去要求团队，减少很多职责不清晰，互相甩锅的情况。</p><p>最后你还要明确自己的做事风格。在职场中我一旦认定要做的事，就会不达目的不罢休。在大公司互相扯皮的事情很多，有时候小伙伴对外去谈一个接口合作，对方常常糊弄，不想做，最后就会委屈地用别扭的方案去实现。每当这个时候，我都会冲出去，三番五次地聊，直到对方同意，让方案回归到合理的路上。后来合作多了，别人知道我的原则，很多做事上的撕扯就少多了。</p><p>找到自己做事的原则和风格，你就慢慢地理顺职场与自己的关系了。这层关系理顺了，加上我们读懂了职场的游戏规则，工作的幸福感就会大幅提升。</p><h2 id="聊聊发展" tabindex="-1">聊聊发展 <a class="header-anchor" href="#聊聊发展" aria-label="Permalink to &quot;聊聊发展&quot;">​</a></h2><p>你合作的上下游中，每个角色的利益诉求是什么？又有哪些恐惧？找一个与你当下关联最密切的合作人，思考应该如何去管理 TA 的利益诉求和恐惧？欢迎留言讨论。</p><p>如果觉得有所收获，也可以把课程分享给更多的朋友，一起学习程序员职业规划手册，心里不慌，脚下不乱，做好每一天的成长。</p>',76)])])}const u=p(l,[["render",n]]);export{c as __pageData,u as default};
